package hr.hrg.jcodebuddy.generated;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * The parser, run over this repository's <b>real</b> generated files.
 *
 * <p>Every other test in this module builds the source text it parses, which means the parser is only ever
 * measured against shapes written by the same person, for it, on the same day. This class removes that:
 * it walks the tree, finds the files the actual generators emitted, and parses them. A parser that reports
 * issues on real generated output is broken in a way its own tests cannot see, and this is the test that
 * would have caught it.
 *
 * <p>It is also the standing proof of the property DEC-035 claims: the parser has never seen these
 * generators. Nothing in this file references one, and it still reads their output correctly.
 *
 * <p>The module has no dependencies, so this uses the JDK for the walk rather than a helper. It resolves
 * the repository root from the working directory, which is the module directory under a reactor build, and
 * skips itself when the tree is not there instead of failing on a checkout layout it does not know.
 */
class GeneratedFilesInThisRepositoryTest {

    /** Derived and vendored trees, which are not anybody's committed source. */
    private static final List<String> SKIP_DIRECTORIES =
            List.of("target", "node_modules", ".git", ".kilo", "proto", "build", "dist", ".idea");

    /**
     * The source root the entity generator writes into, and the only tree this test needs to read.
     *
     * <p>Deliberately not the whole repository. A generator's generated files are committed to a known
     * source root — that is what `--java-out` is for — so searching the tree finds them without depending
     * on a walk of every module, and a failure here means the generator's output regressed rather than
     * that a directory layout changed. Measured: 699 {@code .java} files in this repository and 15 of them
     * carry the file marker, and all 15 are under this root.
     */
    private static final String GENERATED_SOURCE_ROOT = "hipster-entity-example/src/main/java";

    /** The file marker, which is what makes a file generated by definition. */
    private static final String FILE_MARKER = "// " + GeneratedCodeMarkers.KEYWORD + " "
            + GeneratedCodeMarkers.SCOPE_FILE + " ";

    private static Path repoRoot() {
        // Under a reactor build the working directory is the module directory, so the root is one up.
        // Which one it actually is is reported rather than assumed: this test's whole value is that it
        // reads the real tree, so a silent skip when the layout is unexpected would make it worthless.
        Path candidate = Path.of("").toAbsolutePath();
        for (int i = 0; i < 3 && candidate != null; i++) {
            if (Files.isDirectory(candidate.resolve("hipster-entity-tooling"))
                    && Files.isRegularFile(candidate.resolve("pom.xml"))) {
                return candidate;
            }
            candidate = candidate.getParent();
        }
        System.out.println("[jcodebuddy-core] repo root not found from working directory "
                + Path.of("").toAbsolutePath());
        return null;
    }

    /** Every committed .java file under the generated source root whose first line is a file marker. */
    private static List<Path> generatedFiles(Path root) throws IOException {
        Path sourceRoot = root.resolve(GENERATED_SOURCE_ROOT);
        if (!Files.isDirectory(sourceRoot)) {
            return List.of();
        }
        List<Path> found = new ArrayList<>();
        try (Stream<Path> walk = Files.walk(sourceRoot)) {
            for (Path path : walk.toList()) {
                if (!path.toString().endsWith(".java") || !Files.isRegularFile(path)) {
                    continue;
                }
                boolean skipped = false;
                for (Path part : sourceRoot.relativize(path)) {
                    if (SKIP_DIRECTORIES.contains(part.toString())) {
                        skipped = true;
                        break;
                    }
                }
                if (skipped) {
                    continue;
                }
                List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
                if (!lines.isEmpty() && lines.get(0).startsWith(FILE_MARKER)) {
                    found.add(path);
                }
            }
        }
        return found;
    }

    @Test
    @DisplayName("every generated file in this repository parses cleanly, with no issue reported")
    void everyGeneratedFileParsesCleanly() throws Exception {
        Path root = repoRoot();
        if (root == null) {
            return; // Not a checkout this test recognises; the unit tests still cover the parser.
        }
        List<Path> files = generatedFiles(root);

        Assertions.assertFalse(files.isEmpty(),
                "the tree has no file carrying the @generated file marker under " + GENERATED_SOURCE_ROOT
                        + ", which would mean the header emission regressed rather than that the parser "
                        + "passed (searched from " + root + ")");

        List<String> failures = new ArrayList<>();
        for (Path path : files) {
            String source = Files.readString(path, StandardCharsets.UTF_8);
            GeneratedCodeParser.Result result = GeneratedCodeParser.parse(source, path.getFileName().toString());
            String name = root.relativize(path).toString().replace('\\', '/');

            if (result.hasIssues()) {
                for (GeneratedCodeParser.MarkerIssue issue : result.issues()) {
                    failures.add(issue.describe(name));
                }
            }
            if (!result.isWhollyGenerated()) {
                failures.add("kind=not_recognised_as_generated, location=" + name
                        + ", cause=the file carries a file marker but the parser did not claim the whole file");
            }
            if (result.blocks().size() != 1) {
                failures.add("kind=unexpected_block_count, location=" + name
                        + ", current=" + result.blocks().size()
                        + ", canonical=1, cause=a wholly-generated file needs exactly the file block");
            }
        }

        Assertions.assertEquals(List.of(), failures,
                "the parser reported problems on real generated output. Each line below is a file the "
                        + "generators emitted and this parser could not read:\n  "
                        + String.join("\n  ", failures)
                        + "\n\n(" + files.size() + " generated file(s) checked)");
    }

    @Test
    @DisplayName("a real generated file's spans cover it exactly, from the marker to the last line")
    void aRealFileSpanIsExact() throws Exception {
        Path root = repoRoot();
        if (root == null) {
            return;
        }
        List<Path> files = generatedFiles(root);
        if (files.isEmpty()) {
            return;
        }

        for (Path path : files) {
            String source = Files.readString(path, StandardCharsets.UTF_8);
            GeneratedCodeParser.Result result = GeneratedCodeParser.parse(source);
            GeneratedBlock file = result.blocks().get(0);

            Assertions.assertEquals(GeneratedBlock.Kind.FILE, file.kind(), path.toString());
            Assertions.assertEquals(1, file.fromLine(),
                    "a file marker is the first line of the file it claims: " + path);
            Assertions.assertEquals(result.lines(), file.toLine(),
                    "and it claims through the last line: " + path);
            Assertions.assertTrue(file.closed(), path.toString());
            Assertions.assertNotNull(file.generator(),
                    "the marker names the generator that wrote it: " + path);
            Assertions.assertTrue(file.generator().contains("."),
                    "and it is a fully qualified name a reader can jump to: " + file.generator());
        }
    }

    @Test
    @DisplayName("the parser reports nothing for this repository's hand-written sources")
    void handWrittenSourcesAreNotClaimed() throws Exception {
        // The other half of recognition, and the one that would fail loudly if the marker pattern were too
        // loose: the majority of this tree is hand-written and none of it is generated.
        Path root = repoRoot();
        if (root == null) {
            return;
        }
        Path handWritten = root.resolve("jcodebuddy-core/src/main/java/hr/hrg/jcodebuddy/generated");

        for (Path path : Files.list(handWritten).toList()) {
            GeneratedCodeParser.Result result =
                    GeneratedCodeParser.parse(Files.readString(path, StandardCharsets.UTF_8), path.toString());

            Assertions.assertFalse(result.hasGeneratedCode(),
                    "this module's own sources are hand-written, so nothing in them is claimed: " + path);
            Assertions.assertFalse(result.hasIssues(),
                    "and a hand-written file is not an error: " + path);
        }
    }
}
